{
  "translations": {
    "L0001": "Cuando cesó la lluvia, nos encontramos otra vez bajo el puente.",
    "L0002": "Hoy pienso volver a solas.",
    "L0003": "Él dijo en voz baja: «Ya está».",
    "L0004": "No sé si esas palabras son perdón o resignación.",
    "L0005": "Quizá mañana vuelva a cruzar el mismo puente.",
    "L0006": "Solo quedaron dos caracteres: 東京."
  },
  "sourceNotes": []
}
